package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// crdtOpIn is one element of a CRDT submission. Exactly one content field is
// meaningful depending on the declared document type: value for a counter,
// elements for a grow-only set.
type crdtOpIn struct {
	ID       string          `json:"id"`
	Value    json.RawMessage `json:"value"`
	Elements []string        `json:"elements"`
}

// crdtOpsRequest is the body of POST .../crdt/ops.
type crdtOpsRequest struct {
	DeviceID string     `json:"deviceId"`
	Type     string     `json:"type"`
	Ops      []crdtOpIn `json:"ops"`
}

// handleCRDTOps accepts a batch of CRDT operations for a document.
//
// The batch declares the document's type; the first accepted batch fixes it to
// counter or gset and every later batch must declare the same type. Two
// batches racing to declare different types serialize in one transaction:
// exactly one takes effect and the other is a 409 that writes nothing.
//
// The strict body contract matches the other JSON endpoints: application/json,
// one JSON value, no trailing content, a non-empty deviceId, a valid type, a
// non-empty ops array of elements with non-empty ids, no in-batch duplicate
// ids, and type-correct content (counter: an integer value; gset: an elements
// array). Any violation is a 400 with zero writes.
func handleCRDTOps(s *store.Store, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	var req crdtOpsRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	if req.Type != store.CRDTTypeCounter && req.Type != store.CRDTTypeGSet {
		writeError(w, http.StatusBadRequest, `type must be "counter" or "gset"`)
		return
	}
	if len(req.Ops) == 0 {
		writeError(w, http.StatusBadRequest, "ops must be a non-empty array")
		return
	}

	ops := make([]store.CRDTOp, len(req.Ops))
	seen := make(map[string]struct{}, len(req.Ops))
	for i, op := range req.Ops {
		if op.ID == "" {
			writeError(w, http.StatusBadRequest, "each op must have a non-empty string id")
			return
		}
		if _, dup := seen[op.ID]; dup {
			writeError(w, http.StatusBadRequest, "duplicate op id within batch: "+op.ID)
			return
		}
		seen[op.ID] = struct{}{}

		crdtOp := store.CRDTOp{ID: op.ID, DeviceID: req.DeviceID}
		switch req.Type {
		case store.CRDTTypeCounter:
			v, ok := parseNonNegativeInt(op.Value)
			if !ok {
				writeError(w, http.StatusBadRequest, "each counter op must carry an integer value >= 0")
				return
			}
			// Re-marshal the canonical integer so idempotency compares the
			// decoded value rather than the client's literal formatting.
			raw, _ := json.Marshal(v)
			crdtOp.Value = raw
		case store.CRDTTypeGSet:
			if len(op.Elements) == 0 {
				writeError(w, http.StatusBadRequest, "each gset op must add at least one element")
				return
			}
			for _, element := range op.Elements {
				if element == "" {
					writeError(w, http.StatusBadRequest, "gset elements must be non-empty strings")
					return
				}
			}
			crdtOp.Elements = op.Elements
		}
		ops[i] = crdtOp
	}

	results, err := s.SubmitCRDTOps(documentID, req.Type, ops)
	if err != nil {
		var conflict *store.ErrCRDTConflict
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, conflict.Error())
		default:
			writeError(w, http.StatusInternalServerError, "failed to commit crdt ops")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"results": results})
}

// handleCRDTState returns the document's current type and merged result. A
// document with no committed operations has no state yet and answers 404.
func handleCRDTState(s *store.Store, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	state, err := s.GetCRDTState(documentID)
	if err != nil {
		if errors.Is(err, store.ErrCRDTNotFound) {
			writeError(w, http.StatusNotFound, "crdt state not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to load crdt state")
		return
	}

	// Marshal through a concrete shape so the value stays a native JSON number
	// or array rather than an escaped blob.
	writeJSON(w, http.StatusOK, map[string]any{
		"type":  state.Type,
		"value": json.RawMessage(state.Value),
	})
}

// malformedCRDTPath reports whether p targets the CRDT namespace but is not at
// one of the two exact endpoints:
//
//	POST/GET /v1/documents/{documentID}/crdt/ops
//	GET      /v1/documents/{documentID}/crdt/state
//
// A missing/empty document id, a trailing slash, extra path segments, or a
// "crdt" segment in any position short of that shape is a malformed 400 rather
// than ServeMux's redirect or plain-text 404/405, so the new endpoints never
// redirect or emit HTML. The keyword is matched only past the documentID
// position, so a document literally named "crdt" keeps its ordinary routes.
func malformedCRDTPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	for i, seg := range segs {
		if seg == "crdt" && i > 0 {
			if len(segs) != 3 || segs[0] == "" {
				return true
			}
			switch segs[2] {
			case "ops", "state":
				return false
			default:
				return true
			}
		}
	}
	return false
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"time"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// subscribePageLimit is the page size used while replaying changes already
// committed after the subscription cursor. It matches the largest page the
// paginated read endpoint accepts, so catch-up and reads stay page-aligned.
const subscribePageLimit = 1000

// wsCloseEchoWait bounds how long a server-initiated close waits for the
// client's close echo before the deferred TCP teardown.
const wsCloseEchoWait = 500 * time.Millisecond

// handleSubscribe is the WebSocket document subscription mounted under the
// session view:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/changes/subscribe?cursor=N
//
// The subscription identity is entirely the existing session: the session's
// owning device is the only credential. Validation happens entirely before
// the 101 handshake and writes nothing:
//
//  1. cursor must be a non-negative decimal integer (400 JSON otherwise),
//  2. the request must carry a valid WebSocket upgrade handshake (400 JSON),
//  3. the session must currently exist (404 JSON),
//  4. its device must currently hold permission for the document (403 JSON).
//
// After the upgrade the server first sends every committed change with a
// cursor greater than the starting cursor — paged in cursor order, one text
// frame per record in the exact {"id","deviceId","payload","cursor"} shape of
// a paginated read row — then seamlessly continues with changes committed by
// any write path (batch post, merge, restore, replay). Frames are never
// reordered or coalesced; a later read from the last observed cursor returns
// the same rows. The connection is push-only: inbound data frames are read
// and discarded, only close/ping control frames are honored.
//
// A permission revoked after the upgrade ends the subscription with close
// code 4403 and no further frame follows; a termination signal ends every
// subscription with 1001. A client disconnect simply unregisters — like long
// polling, a subscription writes no change, cursor or other record.
func handleSubscribe(s *store.Store, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	// Parameter shape first: a bad cursor is a 400 even when the session or
	// handshake is also bad, matching the session-scoped read ordering.
	cursor, ok := parseSubscribeCursor(w, r)
	if !ok {
		return
	}
	if !checkWebSocketUpgrade(r) {
		writeError(w, http.StatusBadRequest, "a WebSocket upgrade handshake is required")
		return
	}

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}
	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	conn, err := upgradeWebSocket(w, r)
	if err != nil {
		// The 101 response could not be written and the connection has been
		// hijacked (or is gone), so no JSON error can be produced. Nothing
		// was registered or written to the store.
		return
	}

	serveSubscription(r, s, conn, documentID, deviceID, cursor)
}

// parseSubscribeCursor validates the mandatory cursor query parameter: it
// must be present and a decimal non-negative integer. Negative, fractional
// and non-numeric values are a 400 JSON error; signs and adornments are
// rejected.
func parseSubscribeCursor(w http.ResponseWriter, r *http.Request) (int64, bool) {
	raw := r.URL.Query().Get("cursor")
	// parseCursorPath accepts only decimal digits (no sign, fraction or
	// exponent); a missing parameter is an empty raw and is rejected too.
	cursor, ok := parseCursorPath(raw)
	if !ok {
		writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
		return 0, false
	}
	return cursor, true
}

// serveSubscription runs one upgraded connection to completion. It registers
// before the first log read (a commit landing during catch-up is therefore
// never missed), then alternates a flush phase — drain every page of changes
// past the last sent cursor — and a park phase on the wake channel. A revoke
// is acted on only after the committed tail is flushed, so a commit that was
// authorized when it landed is still delivered ahead of the 4403. The method
// returns when the client leaves, permission is revoked or the store starts
// closing; the hijacked connection is closed on exit.
func serveSubscription(r *http.Request, s *store.Store, conn *wsConn, documentID, deviceID string, cursor int64) {
	// Registration precedes the first read: the wake channel is buffered, so
	// a commit during a read leaves a pending wake that makes the next park
	// return immediately — no wake is lost. The revoked channel closes once
	// if access is withdrawn, and that event survives a racing re-grant.
	wakeCh, revokedCh, unregister := s.AddSubscription(documentID, deviceID)
	defer func() {
		unregister()
		_ = conn.NetClose()
	}()

	clientGone := make(chan struct{})
	go func() {
		defer close(clientGone)
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				// A malformed frame ends the connection with the RFC
				// protocol-error code; a client close is already echoed
				// inside ReadMessage; a network drop needs no frame.
				var protoErr *wsProtocolErrorString
				if errors.As(err, &protoErr) {
					_ = conn.Close(wsCloseProtocolError, "protocol error")
				}
				return
			}
			// Push-only channel: an inbound data frame is read and
			// discarded; the client cannot mutate the log over it.
		}
	}()

	// checkEnd non-blockingly maps a closing store to 1001 and a sticky
	// revoke to 4403; it returns true when the subscription must end. A
	// termination signal takes precedence: SIGTERM must end every
	// subscription with 1001 even if a revoke is also pending.
	checkEnd := func() bool {
		if s.Closing() {
			endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
			return true
		}
		select {
		case <-revokedCh:
			endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
			return true
		default:
		}
		return false
	}

	position := cursor
	first := true
	for {
		if !first {
			// Park until a commit, a sticky revoke or the termination signal
			// wakes us. r.Context() covers a non-shutdown cancel; the read
			// pump covers a client disconnect.
			select {
			case <-wakeCh:
				// Drain any coalesced follow-up signal as well; the flush
				// below reconciles every case by re-reading from the last
				// sent cursor.
				select {
				case <-wakeCh:
				default:
				}
			case <-revokedCh:
				if s.Closing() {
					endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
					return
				}
				endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
				return
			case <-clientGone:
				return
			case <-r.Context().Done():
				return
			}
			if s.Closing() {
				endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
				return
			}
		}
		first = false

		// Flush phase: page every change past position in cursor order. A
		// termination signal or a revoke is honored between pages/rows so a
		// large catch-up cannot delay the closing frame. A revoke arriving
		// while the final already-authorized tail is in flight is checked
		// after the inner loop, so that tail still goes out first.
		for {
			if checkEnd() {
				return
			}
			select {
			case <-clientGone:
				return
			case <-r.Context().Done():
				return
			default:
			}

			changes, _, err := s.ListChanges(documentID, position, subscribePageLimit)
			if err != nil {
				_ = conn.Close(wsCloseInternalError, "internal error")
				return
			}
			for i := range changes {
				if checkEnd() {
					return
				}
				raw, marshalErr := json.Marshal(changes[i])
				if marshalErr != nil {
					_ = conn.Close(wsCloseInternalError, "internal error")
					return
				}
				if writeErr := conn.WriteText(raw); writeErr != nil {
					return
				}
				position = changes[i].Cursor
			}
			if len(changes) < subscribePageLimit {
				break
			}
		}

		// Caught up. A revoke that arrived during the last page (its tail was
		// just flushed) now ends the subscription; otherwise loop and park.
		// Closing still wins over a pending revoke.
		if checkEnd() {
			return
		}
	}
}

// endSubscription sends the mandated closing frame and briefly waits for the
// read pump to observe the peer's close echo, so a graceful close reaches the
// client instead of being truncated by the deferred TCP teardown. It returns
// promptly if the peer is already gone; the caller's deferred NetClose drops
// the socket either way.
func endSubscription(conn *wsConn, clientGone <-chan struct{}, code int, reason string) {
	_ = conn.Close(code, reason)
	timer := time.NewTimer(wsCloseEchoWait)
	defer timer.Stop()
	select {
	case <-clientGone:
	case <-timer.C:
	}
}

// CRDT state sits beside the change log as an independent, automatically
// mergeable state layer. A document's CRDT type is declared with its first
// operation batch — "counter" or "gset" (a grow-only set) — and never changes
// afterward; two batches declaring different types concurrently serialize in
// one transaction and exactly one takes effect.
//
// A counter operation carries the originating device's accumulated
// contribution. Each device's contribution only moves forward (a regressing
// value is an ErrCRDTConflict and changes nothing), and the merged state is the
// sum of every device's maximum contribution — a PN-free grow-only counter
// (GCounter), so the merge is commutative, associative and idempotent.
//
// A gset operation adds elements; the merged state is the union of every
// accepted element, presented in ascending order. Re-adding an element does
// not change the state.
//
// Every operation carries a stable, client-supplied id, unique per document.
// Re-posting the same id with the same content and origin is idempotent; the
// same id with different content or a different device is an
// ErrCRDTConflict and leaves the state untouched. Operations and the merged
// result commit together in one serialized transaction and are durable: the
// decisions and the merged state are unchanged after a restart.
//
// The CRDT layer shares the registration/permission layer with the rest of the
// service: an unregistered device yields ErrDeviceNotFound (404) and a revoked
// device yields ErrPermissionDenied (403), before any CRDT content is observed.
// It never touches the change log, document cursors, snapshots or the
// subscription machinery.

package store

import (
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
)

// CRDT document types.
const (
	// CRDTTypeCounter is the grow-only counter: the merged value is the sum of
	// each device's maximum accumulated contribution.
	CRDTTypeCounter = "counter"
	// CRDTTypeGSet is the grow-only set: the merged value is the union of all
	// added elements.
	CRDTTypeGSet = "gset"
)

// ErrCRDTNotFound reports that no CRDT operation has ever been committed for
// the document, so it has neither a type nor a merged state yet. The caller
// maps it to 404.
var ErrCRDTNotFound = errors.New("crdt state not found")

// ErrCRDTConflict reports a rejected CRDT batch: the document's type is
// already fixed to another type, a counter contribution regressed, or an
// operation id already exists with different content or origin. Nothing is
// written; the caller maps it to 409.
type ErrCRDTConflict struct {
	// ID is the conflicting operation id when one is known; it is empty for a
	// document-level conflict (a mismatched declared type).
	ID string
	// Reason carries a short, machine-facing description of the conflict.
	Reason string
}

func (e *ErrCRDTConflict) Error() string {
	if e.ID != "" {
		return fmt.Sprintf("crdt conflict for operation %q: %s", e.ID, e.Reason)
	}
	return "crdt conflict: " + e.Reason
}

// CRDTOp is one element of an inbound CRDT batch.
//
// For a counter, Value is the device's accumulated contribution: it must be a
// JSON number that is a non-negative integer, and it may never decrease for
// the same device. Elements is unused.
//
// For a gset, Elements lists the strings the operation adds to the set and
// must be non-empty; Value is unused.
type CRDTOp struct {
	ID       string          // client-supplied stable id, unique per document
	DeviceID string          // originating device (shared by the whole batch)
	Value    json.RawMessage // counter: the device's accumulated contribution
	Elements []string        // gset: elements to add
}

// CRDTState is a document's merged CRDT state.
//
// Value holds the type-specific merged result: for a counter it decodes to the
// JSON integer sum of per-device maxima; for a gset it decodes to the sorted
// JSON array of every accepted element (an empty set is []).
type CRDTState struct {
	Type  string          `json:"type"`
	Value json.RawMessage `json:"value"`
}

// CRDTResult reports the outcome for one element of an accepted CRDT batch.
type CRDTResult struct {
	ID      string `json:"id"`
	Created bool   `json:"created"`
}

// crdtSchema is appended to the schema created in init.
const crdtSchema = `
CREATE TABLE IF NOT EXISTS crdt_documents (
	document_id TEXT NOT NULL PRIMARY KEY,
	type        TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS crdt_ops (
	document_id TEXT NOT NULL,
	id          TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	value       BLOB,
	PRIMARY KEY (document_id, id)
);
CREATE TABLE IF NOT EXISTS crdt_counter_values (
	document_id TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	value       INTEGER NOT NULL,
	PRIMARY KEY (document_id, device_id)
);
CREATE TABLE IF NOT EXISTS crdt_set_elements (
	document_id TEXT NOT NULL,
	element     TEXT NOT NULL,
	PRIMARY KEY (document_id, element)
);
`

// SubmitCRDTOps validates and commits one CRDT batch atomically.
//
// declaredType is the type the client asserts for the document
// ("counter" or "gset"). It fixes the type on the document's first batch;
// every later batch must declare the same type. Two batches declaring
// different types race in one serialized transaction, so exactly one wins and
// the other gets an *ErrCRDTConflict (409).
//
// The device is gated first (ErrDeviceNotFound / ErrPermissionDenied) before
// any CRDT content is read. Every operation is then resolved against the
// committed history: a repeated id is idempotent only with the same device and
// content, otherwise it is an *ErrCRDTConflict; a counter contribution below
// the device's current maximum is likewise an *ErrCRDTConflict. Any failure
// rejects the whole batch. Results come back in request order.
func (s *Store) SubmitCRDTOps(documentID, declaredType string, ops []CRDTOp) ([]CRDTResult, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	deviceID := ops[0].DeviceID

	// Registration and permission are enforced before any CRDT content is
	// observed, so a rejected submission cannot reveal type or state.
	var deviceExists bool
	if err := tx.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&deviceExists); err != nil {
		return nil, err
	}
	if !deviceExists {
		return nil, ErrDeviceNotFound
	}
	var storedAuth int
	err = tx.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&storedAuth)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// No deviation row: devices start authorized.
	case err != nil:
		return nil, err
	default:
		if storedAuth == 0 {
			return nil, ErrPermissionDenied
		}
	}

	// Resolve the document type: fixed on the first accepted batch.
	var docType string
	err = tx.QueryRow(
		`SELECT type FROM crdt_documents WHERE document_id = ?`, documentID,
	).Scan(&docType)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// First batch for this document: its declared type wins the race.
		if _, err := tx.Exec(
			`INSERT INTO crdt_documents (document_id, type) VALUES (?, ?)`,
			documentID, declaredType,
		); err != nil {
			return nil, err
		}
		docType = declaredType
	case err != nil:
		return nil, err
	default:
		if docType != declaredType {
			return nil, &ErrCRDTConflict{
				Reason: fmt.Sprintf("document type is already %q", docType),
			}
		}
	}

	results := make([]CRDTResult, len(ops))

	switch docType {
	case CRDTTypeCounter:
		if err := applyCounterOps(tx, documentID, ops, results); err != nil {
			return nil, err
		}
	case CRDTTypeGSet:
		if err := applyGSetOps(tx, documentID, ops, results); err != nil {
			return nil, err
		}
	}

	if err := tx.Commit(); err != nil {
		return nil, err
	}
	return results, nil
}

// applyCounterOps resolves and applies every counter operation inside tx. A
// repeated id is idempotent only with the same device and contribution. A new
// id with a contribution below the device's stored maximum regresses the
// counter and is rejected; an equal contribution is an accepted no-op; a
// larger one advances the device's maximum.
func applyCounterOps(tx *sql.Tx, documentID string, ops []CRDTOp, results []CRDTResult) error {
	for i, op := range ops {
		value, err := decodeCounterValue(op.Value)
		if err != nil {
			return &ErrCRDTConflict{ID: op.ID, Reason: err.Error()}
		}

		var existingDevice string
		var existingValue []byte
		err = tx.QueryRow(
			`SELECT device_id, value FROM crdt_ops WHERE document_id = ? AND id = ?`,
			documentID, op.ID,
		).Scan(&existingDevice, &existingValue)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			// New id: enforce monotonicity against this device's maximum.
			var current sql.NullInt64
			if scanErr := tx.QueryRow(
				`SELECT value FROM crdt_counter_values WHERE document_id = ? AND device_id = ?`,
				documentID, op.DeviceID,
			).Scan(&current); scanErr != nil && !errors.Is(scanErr, sql.ErrNoRows) {
				return scanErr
			}
			if current.Valid && value < current.Int64 {
				return &ErrCRDTConflict{
					ID:     op.ID,
					Reason: "counter contribution must not decrease",
				}
			}
			if _, err := tx.Exec(
				`INSERT INTO crdt_ops (document_id, id, device_id, value) VALUES (?, ?, ?, ?)`,
				documentID, op.ID, op.DeviceID, []byte(op.Value),
			); err != nil {
				return err
			}
			if !current.Valid || value > current.Int64 {
				if _, err := tx.Exec(
					`INSERT INTO crdt_counter_values (document_id, device_id, value) VALUES (?, ?, ?)
					 ON CONFLICT (document_id, device_id) DO UPDATE SET value = excluded.value`,
					documentID, op.DeviceID, value,
				); err != nil {
					return err
				}
			}
			results[i] = CRDTResult{ID: op.ID, Created: true}
		case err != nil:
			return err
		default:
			if existingDevice != op.DeviceID || !jsonEqual(existingValue, op.Value) {
				return &ErrCRDTConflict{
					ID:     op.ID,
					Reason: "operation id already exists with a different device or value",
				}
			}
			results[i] = CRDTResult{ID: op.ID, Created: false}
		}
	}
	return nil
}

// applyGSetOps resolves and applies every grow-only-set operation inside tx.
// A repeated id is idempotent only with the same device and the same set of
// elements (element order is irrelevant to the merge). New elements are
// inserted into the union table; re-adding an element changes nothing.
func applyGSetOps(tx *sql.Tx, documentID string, ops []CRDTOp, results []CRDTResult) error {
	for i, op := range ops {
		var existingDevice string
		var existingElements []byte
		err := tx.QueryRow(
			`SELECT device_id, value FROM crdt_ops WHERE document_id = ? AND id = ?`,
			documentID, op.ID,
		).Scan(&existingDevice, &existingElements)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			// New id; insert the op and its elements below.
		case err != nil:
			return err
		default:
			if existingDevice != op.DeviceID || !stringSetEqual(existingElements, op.Elements) {
				return &ErrCRDTConflict{
					ID:     op.ID,
					Reason: "operation id already exists with a different device or elements",
				}
			}
			results[i] = CRDTResult{ID: op.ID, Created: false}
			continue
		}

		if _, err := tx.Exec(
			`INSERT INTO crdt_ops (document_id, id, device_id, value) VALUES (?, ?, ?, ?)`,
			documentID, op.ID, op.DeviceID, []byte(encodeSetElements(op.Elements)),
		); err != nil {
			return err
		}
		for _, element := range op.Elements {
			// The union table is an identity insert: a repeated element simply
			// exists once.
			if _, err := tx.Exec(
				`INSERT OR IGNORE INTO crdt_set_elements (document_id, element) VALUES (?, ?)`,
				documentID, element,
			); err != nil {
				return err
			}
		}
		results[i] = CRDTResult{ID: op.ID, Created: true}
	}
	return nil
}

// decodeCounterValue requires raw to be a non-negative JSON integer with no
// fraction or exponent. Floats, strings, booleans and null are rejected at the
// API boundary; a malformed integer here means the caller skipped validation.
func decodeCounterValue(raw json.RawMessage) (int64, error) {
	var n int64
	if err := json.Unmarshal(raw, &n); err != nil || n < 0 {
		return 0, errors.New("counter value must be a non-negative integer")
	}
	return n, nil
}

// encodeSetElements renders the elements of one gset operation as a JSON array
// for durable storage of the original operation content.
func encodeSetElements(elements []string) json.RawMessage {
	raw, err := json.Marshal(elements)
	if err != nil {
		// Strings always marshal.
		return json.RawMessage("[]")
	}
	return raw
}

// stringSetEqual reports whether raw (a JSON array of strings stored for a
// prior gset operation) contains exactly the elements of want, ignoring
// duplicates and order: the content of a set operation is the set of elements.
func stringSetEqual(raw json.RawMessage, want []string) bool {
	var got []string
	if err := json.Unmarshal(raw, &got); err != nil {
		return false
	}
	set := make(map[string]struct{}, len(got))
	for _, e := range got {
		set[e] = struct{}{}
	}
	for _, e := range want {
		if _, ok := set[e]; !ok {
			return false
		}
		delete(set, e)
	}
	return len(set) == 0
}

// GetCRDTState returns the merged CRDT state for documentID. A document with
// no committed operations yields ErrCRDTNotFound (the caller answers 404).
//
// The merged value is derived from the per-device maxima (counter) or the
// union table (gset), not cached: it is exactly what any equivalent batch
// order would converge to.
func (s *Store) GetCRDTState(documentID string) (CRDTState, error) {
	var docType string
	err := s.db.QueryRow(
		`SELECT type FROM crdt_documents WHERE document_id = ?`, documentID,
	).Scan(&docType)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return CRDTState{}, ErrCRDTNotFound
	case err != nil:
		return CRDTState{}, err
	}

	switch docType {
	case CRDTTypeCounter:
		var total int64
		if err := s.db.QueryRow(
			`SELECT COALESCE(SUM(value), 0) FROM crdt_counter_values WHERE document_id = ?`,
			documentID,
		).Scan(&total); err != nil {
			return CRDTState{}, err
		}
		raw, err := json.Marshal(total)
		if err != nil {
			return CRDTState{}, err
		}
		return CRDTState{Type: docType, Value: raw}, nil
	case CRDTTypeGSet:
		rows, err := s.db.Query(
			`SELECT element FROM crdt_set_elements WHERE document_id = ? ORDER BY element ASC`,
			documentID,
		)
		if err != nil {
			return CRDTState{}, err
		}
		elements := make([]string, 0)
		for rows.Next() {
			var element string
			if err := rows.Scan(&element); err != nil {
				_ = rows.Close()
				return CRDTState{}, err
			}
			elements = append(elements, element)
		}
		if err := rows.Err(); err != nil {
			_ = rows.Close()
			return CRDTState{}, err
		}
		_ = rows.Close()
		raw, err := json.Marshal(elements)
		if err != nil {
			return CRDTState{}, err
		}
		return CRDTState{Type: docType, Value: raw}, nil
	default:
		return CRDTState{}, fmt.Errorf("unknown crdt type %q stored for document", docType)
	}
}

