99	// NewHandler builds the public HTTP surface backed by s.
100	func NewHandler(s *store.Store) http.Handler {
101		mux := http.NewServeMux()
102	
103		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
104			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
105		})
106	
107		mux.HandleFunc("POST /v1/devices", func(w http.ResponseWriter, r *http.Request) {
108			handleRegisterDevice(s, w, r)
109		})
110		// Non-POST verbs on the exact collection path: the method-less pattern is
111		// less specific than POST above, so it only catches the rest and answers a
112		// JSON 404 instead of ServeMux's slash redirect.
113		mux.HandleFunc("/v1/devices", func(w http.ResponseWriter, _ *http.Request) {
114			writeError(w, http.StatusNotFound, "unknown device path")
115		})
116		mux.HandleFunc("/v1/sessions", func(w http.ResponseWriter, _ *http.Request) {
117			writeError(w, http.StatusNotFound, "unknown session path")
118		})
119		mux.HandleFunc("POST /v1/devices/{deviceId}/sessions", func(w http.ResponseWriter, r *http.Request) {
120			handleCreateSession(s, w, r)
121		})
122		mux.HandleFunc("DELETE /v1/devices/{deviceId}/sessions/{sessionId}", func(w http.ResponseWriter, r *http.Request) {
123			handleDeleteSession(s, w, r)
124		})
125		mux.HandleFunc("POST /v1/devices/{deviceId}/attachments", func(w http.ResponseWriter, r *http.Request) {
126			handleCreateAttachment(s, w, r)
127		})
128		mux.HandleFunc("PUT /v1/devices/{deviceId}/attachments/{attachmentId}/chunks/{index}", func(w http.ResponseWriter, r *http.Request) {
129			handlePutChunk(s, w, r)
130		})
131		mux.HandleFunc("POST /v1/devices/{deviceId}/attachments/{attachmentId}/complete", func(w http.ResponseWriter, r *http.Request) {
132			handleCompleteAttachment(s, w, r)
133		})
134		mux.HandleFunc("GET /v1/devices/{deviceId}/attachments/{attachmentId}", func(w http.ResponseWriter, r *http.Request) {
135			handleGetAttachment(s, w, r)
136		})
137		mux.HandleFunc("GET /v1/devices/{deviceId}/attachments/{attachmentId}/chunks/{index}", func(w http.ResponseWriter, r *http.Request) {
138			handleGetChunk(s, w, r)
139		})
140		mux.HandleFunc("GET /v1/sessions/{sessionId}/documents/{documentId}/changes", func(w http.ResponseWriter, r *http.Request) {
141			handleSessionChanges(s, w, r)
142		})
143		mux.HandleFunc("GET /v1/sessions/{sessionId}/documents/{documentId}/changes/subscribe", func(w http.ResponseWriter, r *http.Request) {
144			handleSubscribe(s, w, r)
145		})
146		// Non-GET verbs on the subscribe path get a JSON 400 rather than
147		// ServeMux's plain-text 405: the endpoint's only method is GET.
148		mux.HandleFunc("/v1/sessions/{sessionId}/documents/{documentId}/changes/subscribe", func(w http.ResponseWriter, _ *http.Request) {
149			writeError(w, http.StatusBadRequest, "method is not allowed on this path")
150		})
