152		// ServeMux's plain-text one: every failure of a new endpoint answers JSON.
153		// Exact method-patterns above take precedence over these subtree patterns.
154		mux.HandleFunc("/v1/devices/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
155			writeError(w, http.StatusNotFound, "unknown device/session path")
156		})
157		mux.HandleFunc("/v1/sessions/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
158			writeError(w, http.StatusNotFound, "unknown session path")
159		})
