224	// emptyIDGuard rejects requests carrying an empty path identifier with a 400
225	// JSON error instead of letting ServeMux emit its HTML redirect or a
226	// plain-text 404.
227	//
228	// The document family keeps its original rule (an empty documentID, i.e. the
229	// prefix /v1/documents//); other odd paths there retain their old response so
230	// the pre-existing surface is unchanged. The new device/session families are
231	// stricter: any doubled slash (an empty deviceId, sessionId or documentId
232	// segment) or a trailing slash (an empty final id) is a 400 JSON error.
233	func emptyIDGuard(next http.Handler) http.Handler {
234		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
235			p := r.URL.Path
236	
237			documentSegmentEmpty := strings.HasPrefix(p, "/v1/documents//")
238			newFamilySegmentEmpty := false
239			if strings.HasPrefix(p, "/v1/devices/") || strings.HasPrefix(p, "/v1/sessions/") {
240				newFamilySegmentEmpty = strings.Contains(p, "//") || strings.HasSuffix(p, "/")
241			}
242	
243			if documentSegmentEmpty || newFamilySegmentEmpty || malformedNewDocumentPath(p) || malformedSubscribePath(p) || malformedCRDTPath(p) {
244				writeError(w, http.StatusBadRequest, "path identifiers must be non-empty strings")
245				return
246			}
247			next.ServeHTTP(w, r)
248		})
249	}
