251	// malformedNewDocumentPath reports whether p targets one of the new
252	// long-poll/replay endpoints but is not that endpoint's exact location: a
253	// missing/empty segment, a trailing slash, extra segments, or a "poll"/"replay"
254	// segment in a position short of the registered shape. ServeMux would answer
255	// those with a 301 redirect or a plain-text 404/405; the new endpoints promise
256	// a JSON error and never a redirect, so every such path is a malformed 400.
257	//
258	// Keywords are matched only past the documentID position, so documents that
259	// happen to be named "poll" or "replay" keep their ordinary merge/snapshot/
260	// changes routes.
261	func malformedNewDocumentPath(p string) bool {
262		rest, ok := strings.CutPrefix(p, "/v1/documents/")
263		if !ok {
264			return false
265		}
266		segs := strings.Split(rest, "/")
267	
268		// Poll endpoint: "poll" must be exactly the third segment, after a
269		// non-empty documentID and "changes".
270		for i, seg := range segs {
271			if seg == "poll" && i > 0 {
272				return !(len(segs) == 3 && segs[0] != "" && segs[1] == "changes")
273			}
274		}
275		// Replay endpoint: "replay" must be exactly the second segment, after a
276		// non-empty documentID.
277		for i, seg := range segs {
278			if seg == "replay" && i > 0 {
279				return !(len(segs) == 2 && segs[0] != "")
280			}
281		}
282		return false
283	}
284	
285	// malformedSubscribePath reports whether p targets the WebSocket subscription
286	// endpoint but is not at its exact location
287	// (/v1/sessions/{sessionId}/documents/{documentId}/changes/subscribe): a
288	// missing "documents"/"changes" segment, an extra segment, or a "subscribe"
289	// segment short of the registered shape. ServeMux would answer those with a
290	// plain-text 404/405; every failure of this endpoint must be a JSON 400
291	// instead. Empty segments are already rejected by the guard itself.
292	//
293	// "subscribe" is treated as the endpoint keyword only in the endpoint's
294	// terminal segment position (the fifth segment, index 4); a session or
295	// document identifier literally named "subscribe" occupies an identifier
296	// position (index 0 or 2) and is therefore left to the ordinary
297	// changes/subscribe routes like any other id.
298	func malformedSubscribePath(p string) bool {
299		rest, ok := strings.CutPrefix(p, "/v1/sessions/")
300		if !ok {
301			return false
302		}
303		segs := strings.Split(rest, "/")
304		for i, seg := range segs {
305			if seg != "subscribe" {
306				continue
307			}
308			// Identifier positions: sessionId (0) and documentId (2). A value of
309			// "subscribe" there is an ordinary identifier, not the endpoint word.
310			if i == 0 || i == 2 {
311				continue
312			}
313			// Endpoint keyword position: the fifth segment must be exactly
314			// "subscribe" with the documents/changes scaffolding around it, and no
315			// segment may follow. Any other occurrence is a malformed path.
316			if i == 4 && len(segs) == 5 &&
317				segs[0] != "" &&
318				segs[1] == "documents" &&
319				segs[2] != "" &&
320				segs[3] == "changes" {
321				return false
322			}
323			return true
324		}
325		return false
326	}
