365	func handleRegisterDevice(s *store.Store, w http.ResponseWriter, r *http.Request) {
366		var req deviceRequest
367		if !decodeJSONBody(w, r, &req) {
368			return
369		}
370		if req.DeviceID == "" {
371			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
372			return
373		}
374	
375		created, err := s.RegisterDevice(req.DeviceID)
376		if err != nil {
377			writeError(w, http.StatusInternalServerError, "failed to register device")
378			return
379		}
380	
381		writeJSON(w, http.StatusOK, map[string]any{"deviceId": req.DeviceID, "created": created})
382	}
