384	func handleCreateSession(s *store.Store, w http.ResponseWriter, r *http.Request) {
385		deviceID := r.PathValue("deviceId") // route pattern + guard guarantee non-empty
386	
387		var req sessionRequest
388		if !decodeJSONBody(w, r, &req) {
389			return
390		}
391		if req.SessionID == "" {
392			writeError(w, http.StatusBadRequest, "sessionId must be a non-empty string")
393			return
394		}
395	
396		created, err := s.CreateSession(deviceID, req.SessionID)
397		if err != nil {
398			var conflict *store.ErrSessionConflict
399			switch {
400			case errors.Is(err, store.ErrDeviceNotFound):
401				writeError(w, http.StatusNotFound, "device not found")
402			case errors.As(err, &conflict):
403				writeError(w, http.StatusConflict, "sessionId already belongs to another device: "+conflict.ID)
404			default:
405				writeError(w, http.StatusInternalServerError, "failed to create session")
406			}
407			return
408		}
409	
410		writeJSON(w, http.StatusOK, map[string]any{"sessionId": req.SessionID, "created": created})
411	}
