565	func handlePostSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
566		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
567	
568		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
569		if err != nil || mediaType != "application/json" {
570			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
571			return
572		}
573	
574		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
575		var req snapshotPostRequest
576		dec := json.NewDecoder(r.Body)
577		if err := dec.Decode(&req); err != nil {
578			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
579			return
580		}
581		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
582			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
583			return
584		}
585	
586		cursor, ok := parseNonNegativeInt(req.Cursor)
587		if !ok {
588			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
589			return
590		}
591		if len(req.State) == 0 {
592			writeError(w, http.StatusBadRequest, "state is required")
593			return
594		}
595	
596		created, err := s.PutSnapshot(documentID, cursor, req.State)
597		if err != nil {
598			var conflict *store.ErrSnapshotConflict
599			switch {
600			case errors.Is(err, store.ErrSnapshotBase):
601				writeError(w, http.StatusBadRequest, "document is unknown or cursor is not an existing cursor")
602				return
603			case errors.As(err, &conflict):
604				writeError(w, http.StatusConflict, "snapshot already exists with a different state")
605				return
606			default:
607				writeError(w, http.StatusInternalServerError, "failed to store snapshot")
608				return
609			}
610		}
611	
612		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "created": created})
613	}
614	
615	func handleGetSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
616		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
617	
618		cursor, ok := parseCursorPath(r.PathValue("cursor"))
619		if !ok {
620			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
621			return
622		}
623	
624		state, err := s.GetSnapshot(documentID, cursor)
625		if err != nil {
626			if errors.Is(err, store.ErrSnapshotNotFound) {
627				writeError(w, http.StatusNotFound, "snapshot not found")
628				return
629			}
630			writeError(w, http.StatusInternalServerError, "failed to load snapshot")
631			return
632		}
633	
634		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "state": state})
635	}
636	
637	func handleRestore(s *store.Store, w http.ResponseWriter, r *http.Request) {
638		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
639	
640		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
641		if err != nil || mediaType != "application/json" {
642			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
643			return
644		}
645	
646		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
647		var req restoreRequest
648		dec := json.NewDecoder(r.Body)
649		if err := dec.Decode(&req); err != nil {
650			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
651			return
652		}
653		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
654			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
655			return
656		}
657	
658		if req.DeviceID == "" {
659			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
660			return
661		}
662		if req.ChangeID == "" {
663			writeError(w, http.StatusBadRequest, "changeId must be a non-empty string")
664			return
665		}
666		// snapshotCursor must be present and a positive integer (no fractions,
667		// strings, booleans, null or zero).
668		if len(req.SnapshotCursor) == 0 {
669			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
670			return
671		}
672		snapshotCursor, ok := parsePositiveInt(req.SnapshotCursor)
673		if !ok {
674			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
675			return
676		}
677	
678		result, err := s.RestoreSnapshot(documentID, req.DeviceID, req.ChangeID, snapshotCursor)
679		if err != nil {
680			var conflict *store.ErrRestoreConflict
681			switch {
682			case errors.Is(err, store.ErrSnapshotNotFound):
683				writeError(w, http.StatusNotFound, "snapshot not found")
684				return
685			case errors.As(err, &conflict):
686				writeError(w, http.StatusConflict, "change id already exists with a different deviceId, snapshotCursor or source state: "+req.ChangeID)
687				return
688			default:
689				writeError(w, http.StatusInternalServerError, "failed to restore snapshot")
690				return
691			}
692		}
693	
694		writeJSON(w, http.StatusOK, result)
695	}
696	
697	// handleSetPermission grants or revokes a registered device's access to one
698	// document. Devices start authorized, so the first revoke is the first write;
699	// repeating the current state is idempotent (changed=false). A rejected
700	// request (bad content type, malformed JSON, trailing content, empty or
701	// mistyped fields, unknown action) is a 400 JSON error and writes nothing; an
702	// unregistered device is a 404 JSON error.
703	func handleSetPermission(s *store.Store, w http.ResponseWriter, r *http.Request) {
704		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
705	
706		var req permissionRequest
707		if !decodeJSONBody(w, r, &req) {
708			return
709		}
710		if req.DeviceID == "" {
711			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
712			return
713		}
714		var authorized bool
715		switch req.Action {
716		case "grant":
717			authorized = true
718		case "revoke":
719			authorized = false
720		default:
721			writeError(w, http.StatusBadRequest, `action must be "grant" or "revoke"`)
722			return
723		}
724	
725		changed, err := s.SetDocumentPermission(documentID, req.DeviceID, authorized)
726		if err != nil {
727			if errors.Is(err, store.ErrDeviceNotFound) {
728				writeError(w, http.StatusNotFound, "device not found")
729				return
730			}
731			writeError(w, http.StatusInternalServerError, "failed to update permission")
732			return
733		}
734	
735		writeJSON(w, http.StatusOK, map[string]any{
736			"deviceId":   req.DeviceID,
737			"authorized": authorized,
738			"changed":    changed,
739		})
740	}
741	
742	// parseCursorPath reports whether raw is a decimal non-negative integer and
743	// returns its value. Signs, fractions and other adornments are rejected.
744	func parseCursorPath(raw string) (int64, bool) {
745		if raw == "" {
746			return 0, false
747		}
748		for _, c := range raw {
749			if c < '0' || c > '9' {
750				return 0, false
751			}
752		}
753		n, err := strconv.ParseInt(raw, 10, 64)
754		if err != nil {
755			return 0, false
756		}
757		return n, true
758	}
759	
760	// parseNonNegativeInt reports whether raw is a JSON integer >= 0. Floats,// strings, booleans, null and negative numbers are rejected.
761	func parseNonNegativeInt(raw json.RawMessage) (int64, bool) {
762		var n int64
763		if err := json.Unmarshal(raw, &n); err != nil || n < 0 {
764			return 0, false
765		}
766		// Guard against values like 1.0 that Unmarshal into int64 on some inputs;
767		// require the literal to contain no fraction or exponent.
768		trimmed := strings.TrimSpace(string(raw))
769		if trimmed == "" || trimmed[0] == '-' {
770			return 0, false
771		}
772		for _, c := range trimmed {
773			if c < '0' || c > '9' {
774				return 0, false
775			}
776		}
777		return n, true
778	}
779	
780	// parsePositiveInt reports whether raw is a JSON integer >= 1. Zero, floats,
781	// strings, booleans, null and negative numbers are rejected.
782	func parsePositiveInt(raw json.RawMessage) (int64, bool) {
783		n, ok := parseNonNegativeInt(raw)
784		if !ok || n < 1 {
785			return 0, false
786		}
787		return n, true
788	}
789	
790	// isJSONObject reports whether raw decodes to a JSON object (not null, an
791	// array or a scalar).
792	func isJSONObject(raw json.RawMessage) bool {
793		var m map[string]json.RawMessage
794		if err := json.Unmarshal(raw, &m); err != nil || m == nil {
795			return false
796		}
797		return true
798	}
799	
800	func handleListChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
801		documentID := r.PathValue("documentID")
802	
803		after, limit, ok := parseChangesQuery(w, r)
804		if !ok {
805			return
806		}
807	
808		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
809		if err != nil {
810			writeError(w, http.StatusInternalServerError, "failed to list changes")
811			return
812		}
813	
814		writeChangesPage(w, changes, nextCursor)
815	}
816	
817	// handleSessionChanges is the session-scoped view of the existing change log:
818	// both path identifiers must be non-empty (the empty-segment guard rejects
819	// those before routing) and the session must currently exist, after which the
820	// query behaves exactly like GET /v1/documents/{documentID}/changes — unless
821	// the session's device has been revoked permission for the document, which is
822	// a 403 JSON error with no changes or nextCursor. Revocation only gates this
823	// read; the change log itself is untouched.
824	func handleSessionChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
825		sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
826		documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty
827	
828		// Malformed query parameters are a request-shape error (400) checked
829		// before the resource lookup (404), matching the snapshot GET ordering.
830		after, limit, ok := parseChangesQuery(w, r)
831		if !ok {
832			return
833		}
834	
835		deviceID, err := s.SessionDevice(sessionID)
836		if err != nil {
837			if errors.Is(err, store.ErrSessionNotFound) {
838				writeError(w, http.StatusNotFound, "session not found")
839				return
840			}
841			writeError(w, http.StatusInternalServerError, "failed to look up session")
842			return
843		}
844	
845		authorized, err := s.DocumentAuthorized(documentID, deviceID)
846		if err != nil {
847			writeError(w, http.StatusInternalServerError, "failed to look up permission")
848			return
849		}
850		if !authorized {
851			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
852			return
853		}
854	
855		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
856		if err != nil {
857			writeError(w, http.StatusInternalServerError, "failed to list changes")
858			return
859		}
860	
861		writeChangesPage(w, changes, nextCursor)
862	}
863	
864	// parseChangesQuery parses the shared after/limit pagination parameters,
865	// writing the documented 400 on an illegal value. It is shared by the
866	// document-scoped and session-scoped change listings so their query semantics
867	// cannot drift apart.
868	func parseChangesQuery(w http.ResponseWriter, r *http.Request) (after, limit int64, ok bool) {
869		q := r.URL.Query()
870	
871		after = 0
872		if raw := q.Get("after"); raw != "" {
873			v, err := strconv.ParseInt(raw, 10, 64)
874			if err != nil || v < 0 {
875				writeError(w, http.StatusBadRequest, "after must be a non-negative integer")
876				return 0, 0, false
877			}
878			after = v
879		}
880	
881		limit = defaultListLimit
882		if raw := q.Get("limit"); raw != "" {
883			v, err := strconv.ParseInt(raw, 10, 64)
884			if err != nil || v < 1 || v > maxListLimit {
885				writeError(w, http.StatusBadRequest, "limit must be an integer between 1 and 1000")
886				return 0, 0, false
887			}
888			limit = v
889		}
890	
891		return after, limit, true
892	}
893	
894	// writeChangesPage renders a change listing page in the shared response shape.
895	func writeChangesPage(w http.ResponseWriter, changes []store.ListedChange, nextCursor int64) {
896		writeJSON(w, http.StatusOK, map[string]any{
897			"changes":    changes,
898			"nextCursor": nextCursor,
899		})
900	}
901	
902	func writeJSON(w http.ResponseWriter, status int, v any) {
903		w.Header().Set("Content-Type", "application/json")
904		w.WriteHeader(status)
905		_ = json.NewEncoder(w).Encode(v)
906	}
907	
908	func writeError(w http.ResponseWriter, status int, message string) {
909		writeJSON(w, status, map[string]string{"error": message})
910	}
911	
912	// handlePollChanges is the long-polling entry over the change log.
913	//
914	// Query params share the existing change-read constraints: after is a
915	// non-negative cursor (default 0) and limit is 1..1000 (default 100); waitMs
916	// is 0..30000 (default 0). Rows already past after return immediately; a known
917	// document caught up to after parks until the first new commit or the wait
918	// deadline; an unknown document returns an empty page with cursor 0 at once.
919	// The response shape is the ordinary page plus a timedOut flag; a deadline
920	// expiry echoes the caller's cursor and never advances it. A client
921	// disconnect simply stops the wait and writes nothing.
922	func handlePollChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
923		documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
924	
925		after, limit, ok := parseChangesQuery(w, r)
926		if !ok {
927			return
928		}
929		q := r.URL.Query()
930		var waitMs int64
931		if raw := q.Get("waitMs"); raw != "" {
932			v, err := strconv.ParseInt(raw, 10, 64)
933			if err != nil || v < 0 || v > maxPollWaitMillis {
934				writeError(w, http.StatusBadRequest, "waitMs must be an integer between 0 and 30000")
935				return
936			}
937			waitMs = v
938		}
939	
940		changes, nextCursor, timedOut, err := s.WaitForChanges(
941			r.Context(), documentID, after, limit, time.Duration(waitMs)*time.Millisecond,
942		)
943		switch {
944		case errors.Is(err, store.ErrStoreClosing):
945			writeError(w, http.StatusServiceUnavailable, "service is shutting down")
946			return
947		case errors.Is(err, context.Canceled), errors.Is(err, context.DeadlineExceeded):
948			// The client went away (or, with waitMs bounded, its deadline lapsed
949			// at the transport): nothing more to write and nothing was stored.
950			return
951		case err != nil:
952			writeError(w, http.StatusInternalServerError, "failed to poll changes")
953			return
954		}
955	
956		writeJSON(w, http.StatusOK, map[string]any{
957			"changes":    changes,
958			"nextCursor": nextCursor,
959			"timedOut":   timedOut,
960		})
961	}
962	
963	// handleReplay retries an offline batch against the existing change log. The
964	// request and per-element semantics mirror POST .../changes — strict
965	// application/json body, non-empty ids, no in-batch duplicates, idempotent only
966	// when deviceId and decoded payload match, otherwise 409 reporting the
967	// conflicting id — with the registration/permission layer enforced first:
968	// 404 for an unregistered device and 403 for a revoked one, neither exposing
969	// change content. The whole batch commits in one serialized transaction that
970	// shares the document's contiguous cursor space with ordinary commits.
971	func handleReplay(s *store.Store, w http.ResponseWriter, r *http.Request) {
972		documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
973	
974		var req replayRequest
975		if !decodeJSONBody(w, r, &req) {
976			return
977		}
978		if req.DeviceID == "" {
979			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
980			return
981		}
982		if req.Operations == nil {
983			writeError(w, http.StatusBadRequest, "operations must be a non-empty array")
984			return
985		}
986		if len(req.Operations) == 0 {
987			writeError(w, http.StatusBadRequest, "operations must be a non-empty array")
988			return
989		}
990	
991		changes := make([]store.Change, len(req.Operations))
992		seen := make(map[string]struct{}, len(req.Operations))
993		for i, op := range req.Operations {
994			if op.ID == "" {
995				writeError(w, http.StatusBadRequest, "each operation must have a non-empty string id")
996				return
997			}
998			if len(op.Payload) == 0 {
999				writeError(w, http.StatusBadRequest, "each operation must carry a JSON payload")
1000				return
1001			}
1002			if _, dup := seen[op.ID]; dup {
1003				writeError(w, http.StatusBadRequest, "duplicate operation id within batch: "+op.ID)
1004				return
1005			}
1006			seen[op.ID] = struct{}{}
1007			changes[i] = store.Change{ID: op.ID, DeviceID: req.DeviceID, Payload: op.Payload}
1008		}
1009	
1010		results, err := s.ReplayChanges(documentID, changes)
1011		if err != nil {
1012			var conflict *store.ErrConflict
1013			switch {
1014			case errors.Is(err, store.ErrDeviceNotFound):
1015				writeError(w, http.StatusNotFound, "device not found")
1016			case errors.Is(err, store.ErrPermissionDenied):
1017				writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
1018			case errors.As(err, &conflict):
1019				writeJSON(w, http.StatusConflict, map[string]string{
1020					"error":      "operation id already exists with different deviceId or payload",
1021					"conflictId": conflict.ID,
1022				})
1023			default:
1024				writeError(w, http.StatusInternalServerError, "failed to replay operations")
1025			}
1026			return
1027		}
1028	
1029		writeJSON(w, http.StatusOK, map[string]any{"results": results})
1030	}
1031

