1	package server
2	
3	import (
4		"bufio"
5		"crypto/sha1"
6		"encoding/base64"
7		"encoding/binary"
8		"errors"
9		"fmt"
10		"io"
11		"net"
12		"net/http"
13		"strings"
14		"sync"
15		"time"
16	)
17	
18	// Minimal RFC 6455 WebSocket server-side codec. The subscription endpoint is
19	// the only WebSocket surface and it is push-only: the server sends text
20	// frames, the client may send control frames (ping/close), and any inbound
21	// data frame is read and discarded. No external dependency is introduced, so
22	// the module keeps its single SQLite dependency.
23	
24	const (
25		wsOpcodeContinue = 0x0
26		wsOpcodeText     = 0x1
27		wsOpcodeBinary   = 0x2
28		wsOpcodeClose    = 0x8
29		wsOpcodePing     = 0x9
30		wsOpcodePong     = 0xA
31	
32		wsFlagFin  = 0x80
33		wsFlagMask = 0x80
34	
35		// wsMaxInboundMessage caps a frame/assembled message sent by the client.
36		// Clients are not expected to send anything but control frames; the cap
37		// only protects the reader.
38		wsMaxInboundMessage = 1 << 20
39		// wsMaxControlPayload is the RFC cap on ping/pong/close payloads.
40		wsMaxControlPayload = 125
41	
42		wsWriteTimeout = 10 * time.Second
43		wsGUID         = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
44	)
45	
46	// Close codes the subscription endpoint emits.
47	const (
48		// wsCloseGoingAway (1001) ends every subscription when the process
49		// receives its termination signal.
50		wsCloseGoingAway = 1001
51		// wsCloseProtocolError (1002) ends a connection whose frames violate
52		// RFC 6455.
53		wsCloseProtocolError = 1002
54		// wsCloseInternalError (1011) ends a connection that hit an unexpected
55		// server failure after the handshake.
56		wsCloseInternalError = 1011
57		// wsClosePermissionRevoked (4403) ends a subscription after its
58		// session's device loses permission for the document.
59		wsClosePermissionRevoked = 4403
60	)
61	
62	// ErrWebSocketClosed is returned by ReadMessage when the peer sends a close
63	// frame; Code/Reason carry the peer's payload when present.
64	var ErrWebSocketClosed = errors.New("websocket close received")
65	
66	type wsCloseError struct {
67		Code   int
68		Reason string
69	}
70	
71	func (e *wsCloseError) Error() string {
72		return fmt.Sprintf("%s: code=%d reason=%q", ErrWebSocketClosed, e.Code, e.Reason)
73	}
74	func (e *wsCloseError) Unwrap() error { return ErrWebSocketClosed }
75	
76	// wsConn is one upgraded WebSocket connection. Writes are serialized; reads
77	// are single-owner (the read pump).
78	type wsConn struct {
79		conn      net.Conn
80		br        *bufio.Reader
81		writeMu   sync.Mutex
82		sentClose bool
83	}
84	
85	// headerContainsToken reports whether a comma-list HTTP header (Connection is
86	// one) carries token, compared case-insensitively per RFC 7230 token rules.
87	func headerContainsToken(header, token string) bool {
88		for _, part := range strings.Split(header, ",") {
89			if strings.EqualFold(strings.TrimSpace(part), token) {
90				return true
91			}
92		}
93		return false
94	}
95	
96	// checkWebSocketUpgrade validates the RFC 6455 opening handshake headers
97	// without hijacking the connection: a failed check is an ordinary 400 JSON
98	// error, so malformed requests never see a redirect, HTML or a 101. It does
99	// not touch the response otherwise.
100	func checkWebSocketUpgrade(r *http.Request) bool {
101		if !headerContainsToken(r.Header.Get("Connection"), "upgrade") ||
102			!strings.EqualFold(r.Header.Get("Upgrade"), "websocket") {
103			return false
104		}
105		if r.Header.Get("Sec-WebSocket-Version") != "13" {
106			return false
107		}
108		key := r.Header.Get("Sec-WebSocket-Key")
109		decoded, err := base64.StdEncoding.DecodeString(key)
110		if err != nil || len(decoded) != 16 {
111			return false
112		}
113		return true
114	}
115	
116	// secWebSocketAccept computes the Sec-WebSocket-Accept handshake value.
117	func secWebSocketAccept(key string) string {
118		sum := sha1.Sum([]byte(key + wsGUID))
119		return base64.StdEncoding.EncodeToString(sum[:])
120	}
121	
122	// upgradeWebSocket hijacks the connection and writes the 101 response. Every
123	// precondition (method, cursor, session, permission, handshake headers) has
124	// already been checked by the caller; from here on failures are reported as
125	// WebSocket close frames rather than HTTP statuses.
126	func upgradeWebSocket(w http.ResponseWriter, r *http.Request) (*wsConn, error) {
127		hj, ok := w.(http.Hijacker)
128		if !ok {
129			return nil, errors.New("connection does not support hijacking")
130		}
131		conn, brw, err := hj.Hijack()
132		if err != nil {
133			return nil, err
134		}
135	
136		accept := secWebSocketAccept(r.Header.Get("Sec-WebSocket-Key"))
137		response := "HTTP/1.1 101 Switching Protocols\r\n" +
138			"Upgrade: websocket\r\n" +
139			"Connection: Upgrade\r\n" +
140			"Sec-WebSocket-Accept: " + accept + "\r\n\r\n"
141		if _, err := io.WriteString(conn, response); err != nil {
142			_ = conn.Close()
143			return nil, err
144		}
145		// Flush anything the HTTP layer buffered before the hijack.
146		if err := brw.Flush(); err != nil {
147			_ = conn.Close()
148			return nil, err
149		}
150		return &wsConn{conn: conn, br: brw.Reader}, nil
151	}
152	
153	// readFrame reads one RFC 6455 frame, unmasking client payloads.
154	func (c *wsConn) readFrame() (fin bool, opcode byte, payload []byte, err error) {
155		header := make([]byte, 2)
156		if _, err = io.ReadFull(c.br, header); err != nil {
157			return false, 0, nil, err
158		}
159		b0, b1 := header[0], header[1]
160		if b0&0x70 != 0 {
161			return false, 0, nil, wsProtocolError("reserved bits must be zero")
162		}
163		fin = b0&wsFlagFin != 0
164		opcode = b0 & 0x0F
165		masked := b1&wsFlagMask != 0
166		length := int64(b1 & 0x7F)
167	
168		switch length {
169		case 126:
170			var ext [2]byte
171			if _, err = io.ReadFull(c.br, ext[:]); err != nil {
172				return false, 0, nil, err
173			}
174			length = int64(binary.BigEndian.Uint16(ext[:]))
175		case 127:
176			var ext [8]byte
177			if _, err = io.ReadFull(c.br, ext[:]); err != nil {
178				return false, 0, nil, err
179			}
180			length = int64(binary.BigEndian.Uint64(ext[:]))
181			if length < 0 {
182				return false, 0, nil, wsProtocolError("frame length too large")
183			}
184		}
185		if opcode == wsOpcodeClose && length > wsMaxControlPayload {
186			return false, 0, nil, wsProtocolError("close frame too large")
187		}
188		if opcode >= wsOpcodeClose && !fin {
189			return false, 0, nil, wsProtocolError("control frame must not be fragmented")
190		}
191		if length > wsMaxInboundMessage {
192			return false, 0, nil, wsProtocolError("frame too large")
193		}
194	
195		var mask [4]byte
196		if masked {
197			if _, err = io.ReadFull(c.br, mask[:]); err != nil {
198				return false, 0, nil, err
199			}
200		}
201		payload = make([]byte, length)
202		if length > 0 {
203			if _, err = io.ReadFull(c.br, payload); err != nil {
204				return false, 0, nil, err
205			}
206		}
207		if masked {
208			for i := range payload {
209				payload[i] ^= mask[i%4]
210			}
211		} else {
212			// RFC 6455 §5.1: a frame from a client MUST be masked.
213			return false, 0, nil, wsProtocolError("client frame is not masked")
214		}
215		return fin, opcode, payload, nil
216	}
217	
218	// ReadMessage returns the next complete data message, answering control
219	// frames inline: a ping is answered with a pong, a pong is ignored, and a
220	// close frame surfaces as ErrWebSocketClosed (the caller echoes it). Fragmented
221	// messages are reassembled in receive order.
222	func (c *wsConn) ReadMessage() (opcode byte, payload []byte, err error) {
223		var assembled []byte
224		started := false
225		messageOpcode := byte(wsOpcodeText)
226	
227		for {
228			fin, frameOpcode, framePayload, frameErr := c.readFrame()
229			if frameErr != nil {
230				return 0, nil, frameErr
231			}
232	
233			switch frameOpcode {
234			case wsOpcodeContinue:
235				if !started {
236					return 0, nil, wsProtocolError("continuation frame without a start frame")
237				}
238				assembled = append(assembled, framePayload...)
239			case wsOpcodeText, wsOpcodeBinary:
240				if started {
241					return 0, nil, wsProtocolError("new data frame before the fragment finished")
242				}
243				started = true
244				messageOpcode = frameOpcode
245				assembled = append(assembled[:0], framePayload...)
246			case wsOpcodeClose:
247				closeErr := parseClosePayload(framePayload)
248				if writeErr := c.writeCloseResponse(framePayload); writeErr != nil {
249					_ = c.conn.Close()
250				}
251				return 0, nil, closeErr
252			case wsOpcodePing:
253				if len(framePayload) > wsMaxControlPayload {
254					return 0, nil, wsProtocolError("ping payload too large")
255				}
256				if pingErr := c.writeControl(wsOpcodePong, framePayload); pingErr != nil {
257					return 0, nil, pingErr
258				}
259				continue
260			case wsOpcodePong:
261				continue
262			default:
263				return 0, nil, wsProtocolError(fmt.Sprintf("unknown opcode %d", frameOpcode))
264			}
265	
266			if len(assembled) > wsMaxInboundMessage {
267				return 0, nil, wsProtocolError("message too large")
268			}
269			if fin {
270				return messageOpcode, assembled, nil
271			}
272		}
273	}
274	
275	func parseClosePayload(payload []byte) error {
276		if len(payload) == 0 {
277			return &wsCloseError{Code: wsCloseGoingAway, Reason: ""}
278		}
279		if len(payload) < 2 {
280			return wsProtocolError("close payload too short")
281		}
282		code := int(binary.BigEndian.Uint16(payload[:2]))
283		return &wsCloseError{Code: code, Reason: string(payload[2:])}
284	}
285	
286	// writeFrame sends one server frame; server frames are never masked.
287	func (c *wsConn) writeFrame(opcode byte, fin bool, payload []byte) error {
288		_ = c.conn.SetWriteDeadline(time.Now().Add(wsWriteTimeout))
289	
290		var b0 byte = opcode
291		if fin {
292			b0 |= wsFlagFin
293		}
294	
295		var header [10]byte
296		header[0] = b0
297		n := 1
298		switch {
299		case len(payload) <= 125:
300			header[1] = byte(len(payload))
301			n++
302		case len(payload) <= 65535:
303			header[1] = 126
304			binary.BigEndian.PutUint16(header[2:4], uint16(len(payload)))
305			n += 3
306		default:
307			header[1] = 127
308			binary.BigEndian.PutUint64(header[2:10], uint64(len(payload)))
309			n += 9
310		}
311		if _, err := c.conn.Write(header[:n]); err != nil {
312			return err
313		}
314		if len(payload) > 0 {
315			if _, err := c.conn.Write(payload); err != nil {
316				return err
317			}
318		}
319		return nil
320	}
321	
322	func (c *wsConn) writeControl(opcode byte, payload []byte) error {
323		c.writeMu.Lock()
324		defer c.writeMu.Unlock()
325		return c.writeFrame(opcode, true, payload)
326	}
327	
328	// WriteText sends one complete text frame.
329	func (c *wsConn) WriteText(payload []byte) error {
330		c.writeMu.Lock()
331		defer c.writeMu.Unlock()
332		if c.sentClose {
333			return errors.New("write after close frame")
334		}
335		return c.writeFrame(wsOpcodeText, true, payload)
336	}
337	
338	// writeCloseResponse echoes a client close frame when the server has not yet
339	// sent its own; it is the read-pump side of the closing handshake.
340	func (c *wsConn) writeCloseResponse(payload []byte) error {
341		c.writeMu.Lock()
342		defer c.writeMu.Unlock()
343		if c.sentClose {
344			return nil
345		}
346		c.sentClose = true
347		return c.writeFrame(wsOpcodeClose, true, payload)
348	}
349	
350	// Close sends the closing handshake with code/reason exactly once. It does not
351	// block on the peer's echo and never reads: the handler owns one read pump,
352	// and concurrent readers on the buffered connection are unsafe. The handler
353	// waits on its read pump and then calls NetClose.
354	func (c *wsConn) Close(code int, reason string) error {
355		c.writeMu.Lock()
356		defer c.writeMu.Unlock()
357		if c.sentClose {
358			return nil
359		}
360		c.sentClose = true
361		payload := make([]byte, 2+len(reason))
362		binary.BigEndian.PutUint16(payload, uint16(code))
363		copy(payload[2:], reason)
364		return c.writeFrame(wsOpcodeClose, true, payload)
365	}
366	
367	// NetClose drops the underlying TCP connection. The read pump unblocks with a
368	// read error; a double close (read pump and handler) is harmless.
369	func (c *wsConn) NetClose() error { return c.conn.Close() }
370	
371	type wsProtocolErrorString struct{ msg string }
372	
373	func (e *wsProtocolErrorString) Error() string { return "websocket protocol error: " + e.msg }
374	
375	func wsProtocolError(msg string) error { return &wsProtocolErrorString{msg: msg} }
376

