290	func setupSession(t *testing.T, srv *httptest.Server, device, session, doc string, seed int) {
291		t.Helper()
292		httpPost := func(path string, body any) {
293			raw, _ := json.Marshal(body)
294			resp, err := srv.Client().Post(srv.URL+path, "application/json", strings.NewReader(string(raw)))
295			if err != nil {
296				t.Fatalf("POST %s: %v", path, err)
297			}
298			defer resp.Body.Close()
299			if resp.StatusCode != http.StatusOK {
300				data, _ := io.ReadAll(resp.Body)
301				t.Fatalf("POST %s = %d %s", path, resp.StatusCode, data)
302			}
303		}
304		httpPost("/v1/devices", map[string]any{"deviceId": device})
305		httpPost("/v1/devices/"+device+"/sessions", map[string]any{"sessionId": session})
306		for i := 0; i < seed; i++ {
307			httpPost("/v1/documents/"+doc+"/changes", map[string]any{
308				"deviceId": device,
309				"changes": []any{
310					map[string]any{"id": fmt.Sprintf("seed-%d", i+1), "payload": map[string]any{"n": i + 1}},
311				},
312			})
313		}
314	}
