func serveCRDTSubscription(r *http.Request, s *store.Store, conn *wsConn, documentID, deviceID string) {
    sub, unregister := s.AddCRDTSubscription(documentID, deviceID)
    defer func() {
        unregister()
        _ = conn.NetClose()
    }()

    clientGone := make(chan struct{})
    go func() {
        defer close(clientGone)
        for {
            if _, _, err := conn.ReadMessage(); err != nil {
                var protoErr *wsProtocolErrorString
                if errors.As(err, &protoErr) {
                    _ = conn.Close(wsCloseProtocolError, "protocol error")
                }
                return
            }
            // Push-only: inbound data frames are read and discarded.
        }
    }()

    checkEnd := func() bool {
        if s.Closing() {
            endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
            return true
        }
        select {
        case <-sub.Revoked():
            endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
            return true
        default:
        }
        return false
    }

    // lastSent is the raw merged value most recently pushed; a queued state
    // identical to it is skipped, so a commit racing the initial read is
    // never pushed twice and a no-op never produces a frame.
    var lastSent json.RawMessage
    send := func(state store.CRDTState) bool {
        if lastSent != nil && bytes.Equal(lastSent, state.Value) {
            return true
        }
        frame, err := marshalCRDTStateFrame(state)
        if err != nil {
            _ = conn.Close(wsCloseInternalError, "internal error")
            return false
        }
        if err := conn.WriteText(frame); err != nil {
            return false
        }
        lastSent = state.Value
        return true
    }

    // The initial merged state goes first: a document with no CRDT operation
    // yet pushes nothing and simply waits for the first state to appear.
    if s.Closing() {
        endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
        return
    }
    state, err := s.GetCRDTState(documentID)
    switch {
    case errors.Is(err, store.ErrCRDTNotFound):
        // No state yet: stay silent until the first commit.
    case err != nil:
        _ = conn.Close(wsCloseInternalError, "internal error")
        return
    default:
        if !send(state) {
            return
        }
    }

    for {
        // Park until a committed state change, a sticky revoke, the
        // termination signal or a client disconnect wakes us.
        select {
        case <-sub.Wake():
        case <-sub.Revoked():
            if s.Closing() {
                endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
            } else {
                endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
            }
            return
        case <-clientGone:
            return
        case <-r.Context().Done():
            return
        }
        if s.Closing() {
            endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
            return
        }
        // Drain every queued state in commit order; a revoke or the
        // termination signal is honored between frames.
        for {
            if checkEnd() {
                return
            }
            select {
            case <-clientGone:
                return
            case <-r.Context().Done():
                return
            default:
            }
            states := sub.Drain()
            if len(states) == 0 {
                break
            }
            for _, st := range states {
                if checkEnd() {
                    return
                }
                if !send(st) {
                    return
                }
            }
        }
        if checkEnd() {
            return
        }
    }
