// crdtStateFrame orders the keys of a pushed state message exactly like the
// state read endpoint's body: type, then value.
type crdtStateFrame struct {
    Type  string          `json:"type"`
    Value json.RawMessage `json:"value"`
}

// marshalCRDTStateFrame renders one pushed state as a single-line JSON text
// frame terminated by a newline — byte-for-byte the body the state read
// endpoint returns for the same document.
func marshalCRDTStateFrame(state store.CRDTState) ([]byte, error) {
