36		w, _ = postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
37			"deviceId": "dev-1",
38			"changes":  []any{map[string]any{"id": "c1", "payload": map[string]any{"n": 1}}},
39		})
40		if w.Code != http.StatusOK {
