42		}
43		w, _ = postJSON(t, h, "/v1/documents/doc2/permissions", map[string]any{"deviceId": "dev-1", "action": "revoke"})
44		if w.Code != http.StatusOK {
45			t.Fatal(w.Body.String())
46		}
47	
48		base := "/v1/sessions/sess/documents/doc/changes/subscribe"
49		cases := []struct {
50			name       string
51			method     string
52			target     string
53			upgrade    bool
54			wantStatus int
55		}{
56			{"cursor negative", http.MethodGet, base + "?cursor=-1", true, http.StatusBadRequest},
57			{"cursor fractional", http.MethodGet, base + "?cursor=1.5", true, http.StatusBadRequest},
58			{"cursor non-numeric", http.MethodGet, base + "?cursor=abc", true, http.StatusBadRequest},
59			{"cursor missing", http.MethodGet, base, true, http.StatusBadRequest},
60			{"cursor scientific", http.MethodGet, base + "?cursor=1e3", true, http.StatusBadRequest},
61			{"no upgrade headers", http.MethodGet, base + "?cursor=0", false, http.StatusBadRequest},
62			{"wrong method", http.MethodPost, base + "?cursor=0", false, http.StatusBadRequest},
63			{"empty session segment", http.MethodGet, "/v1/sessions//documents/doc/changes/subscribe?cursor=0", true, http.StatusBadRequest},
64			{"empty document segment", http.MethodGet, "/v1/sessions/sess/documents//changes/subscribe?cursor=0", true, http.StatusBadRequest},
65			{"trailing slash", http.MethodGet, base + "/?cursor=0", true, http.StatusBadRequest},
66			{"extra segment", http.MethodGet, base + "/extra?cursor=0", true, http.StatusBadRequest},
67			{"missing documents segment", http.MethodGet, "/v1/sessions/sess/doc/changes/subscribe?cursor=0", true, http.StatusBadRequest},
68			{"unknown session", http.MethodGet, "/v1/sessions/ghost/documents/doc/changes/subscribe?cursor=0", true, http.StatusNotFound},
69			{"revoked permission", http.MethodGet, "/v1/sessions/sess/documents/doc2/changes/subscribe?cursor=0", true, http.StatusForbidden},
70			// Validation order: a bad cursor wins over a missing session.
71			{"bad cursor before unknown session", http.MethodGet, "/v1/sessions/ghost/documents/doc/changes/subscribe?cursor=x", true, http.StatusBadRequest},
72		}
73	
74		for _, tc := range cases {
75			t.Run(tc.name, func(t *testing.T) {
76				var r *http.Request
77				switch tc.name {
78				case "no upgrade headers", "wrong method":
79					method := http.MethodGet
80					if tc.method != "" {
81						method = tc.method
82					}
83					r = httptest.NewRequest(method, tc.target, nil)
84				default:
85					r = upgradeRequest(tc.target)
86				}
87				rec := httptest.NewRecorder()
88				h.ServeHTTP(rec, r)
89	
90				if rec.Code != tc.wantStatus {
91					t.Fatalf("status = %d, want %d, body = %s", rec.Code, tc.wantStatus, rec.Body.String())
92				}
93				if ct := rec.Header().Get("Content-Type"); ct != "application/json" {
94					t.Fatalf("content-type = %q, want application/json", ct)
95				}
96				var body map[string]string
97				if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil || body["error"] == "" {
98					t.Fatalf("body = %q, want a JSON error", rec.Body.String())
99				}
100			})
101		}
102	}
