538	// The connection is push-only: inbound data frames are accepted and ignored,
539	// never echoed and never written to the log; live pushes continue.
540	func TestSubscribePushOnly(t *testing.T) {
541		srv, st := newWSTestServer(t)
542		setupSession(t, srv, "dev-1", "sess", "doc", 1)
543	
544		conn, resp := dialWS(t, subscribeURL(srv, "sess", "doc", "0"))
545		if conn == nil {
546			t.Fatalf("status = %d", resp.StatusCode)
547		}
548		defer conn.close()
549		if c := conn.readChange(); c.Cursor != 1 {
550			t.Fatalf("seed = %+v", c)
551		}
552	
553		conn.sendText(`{"id":"forged","payload":{"hack":true}}`)
554	
555		// No echo frame arrives before the next real commit.
556		conn.setReadDeadline(300 * time.Millisecond)
557		if _, _, _, ok := conn.readFrameMaybe(); ok {
558			t.Fatal("the server echoed a client frame")
559		}
560		conn.clearReadDeadline()
561	
562		postDocChange(t, srv, "dev-1", "doc", "real", map[string]any{"ok": true})
563		if c := conn.readChange(); c.ID != "real" {
564			t.Fatalf("frame = %+v", c)
565		}
566	
567		// The forged id never reached the log: posting it now allocates a cursor.
568		rows, _, err := st.ListChanges("doc", 0, 1000)
569		if err != nil {
570			t.Fatal(err)
571		}
572		for _, r := range rows {
573			if r.ID == "forged" {
574				t.Fatal("a client frame was written to the change log")
575			}
576		}
577	}
578	
579	// A client ping is answered with a pong and does not disturb the stream.
580	func TestSubscribePingPong(t *testing.T) {
581		srv, _ := newWSTestServer(t)
582		setupSession(t, srv, "dev-1", "sess", "doc", 1)
583	
584		conn, resp := dialWS(t, subscribeURL(srv, "sess", "doc", "0"))
585		if conn == nil {
586			t.Fatalf("status = %d", resp.StatusCode)
587		}
588		defer conn.close()
589		_ = conn.readChange()
590	
591		conn.sendPing()
592		conn.setReadDeadline(2 * time.Second)
593		sawPong := false
594		for {
595			fin, opcode, _, ok := conn.readFrameMaybe()
596			if !ok {
597				break
598			}
599			if opcode == wsOpcodePong && fin {
600				sawPong = true
601				break
602			}
603		}
604		conn.clearReadDeadline()
605		if !sawPong {
606			t.Fatal("no pong received for the ping")
607		}
608	
609		postDocChange(t, srv, "dev-1", "doc", "after-ping", map[string]any{"n": 2})
610		if c := conn.readChange(); c.ID != "after-ping" {
611			t.Fatalf("frame after ping = %+v", c)
612		}
613	}
614	
615	// An unmasked client frame violates RFC 6455 and ends the connection with the
616	// protocol-error close code 1002.
617	func TestSubscribeUnmaskedFrameCloses1002(t *testing.T) {
618		srv, _ := newWSTestServer(t)
619		setupSession(t, srv, "dev-1", "sess", "doc", 1)
620	
621		conn, resp := dialWS(t, subscribeURL(srv, "sess", "doc", "0"))
622		if conn == nil {
623			t.Fatalf("status = %d", resp.StatusCode)
624		}
625		defer conn.close()
626		_ = conn.readChange()
627	
628		// One unmasked single-byte text frame: FIN text, len 1, mask bit clear.
629		if _, err := conn.conn.Write([]byte{0x81, 0x01, 'x'}); err != nil {
630			t.Fatal(err)
631		}
632		conn.setReadDeadline(2 * time.Second)
633		if code := conn.readCloseCode(); code != 1002 {
634			t.Fatalf("close code = %d, want 1002", code)
635		}
636		conn.clearReadDeadline()
637	}
638	
639	// A large existing backlog is paged out in cursor order without gaps.
640	func TestSubscribeLargeCatchUp(t *testing.T) {
641		srv, st := newWSTestServer(t)
642		setupSession(t, srv, "dev-1", "sess", "doc", 0)
643	
644		const total = 2500
645		batch := make([]store.Change, total)
646		for i := range batch {
647			batch[i] = store.Change{
648				ID:       "b-" + itoa(i+1),
649				DeviceID: "dev-1",
650				Payload:  json.RawMessage(`{"i":` + itoa(i+1) + `}`),
651			}
652		}
653		if _, err := st.PostChanges("doc", batch); err != nil {
654			t.Fatal(err)
655		}
656	
657		conn, resp := dialWS(t, subscribeURL(srv, "sess", "doc", "0"))
658		if conn == nil {
659			t.Fatalf("status = %d", resp.StatusCode)
660		}
661		defer conn.close()
662		conn.setReadDeadline(10 * time.Second)
663		for want := int64(1); want <= total; want++ {
664			c := conn.readChange()
665			if c.Cursor != want {
666				t.Fatalf("cursor = %d, want %d (id=%s)", c.Cursor, want, c.ID)
667			}
668		}
669	}
670	
671	// --- helpers ----------------------------------------------------------------
672	
673	func postHTTP(t *testing.T, srv *httptest.Server, path string, body any) int {
674		t.Helper()
675		raw, _ := json.Marshal(body)
676		resp, err := srv.Client().Post(srv.URL+path, "application/json", strings.NewReader(string(raw)))
677		if err != nil {
678			t.Fatalf("POST %s: %v", path, err)
679		}
680		defer resp.Body.Close()
681		_, _ = io.Copy(io.Discard, resp.Body)
682		return resp.StatusCode
683	}
684	
685	func postDocChange(t *testing.T, srv *httptest.Server, device, doc, id string, payload any) {
686		t.Helper()
687		if code := postHTTP(t, srv, "/v1/documents/"+doc+"/changes", map[string]any{
688			"deviceId": device,
689			"changes":  []any{map[string]any{"id": id, "payload": payload}},
690		}); code != http.StatusOK {
691			t.Fatalf("post change %s = %d", id, code)
692		}
693	}
694	
695	func httpGet(t *testing.T, srv *httptest.Server, path string) (int, map[string]any) {
696		t.Helper()
697		resp, err := srv.Client().Get(srv.URL + path)
698		if err != nil {
699			t.Fatalf("GET %s: %v", path, err)
700		}
701		defer resp.Body.Close()
702		data, _ := io.ReadAll(resp.Body)
703		var body map[string]any
704		_ = json.Unmarshal(data, &body)
705		return resp.StatusCode, body
706	}
707	
708	func mustJSON(v any) []byte {
709		b, _ := json.Marshal(v)
710		return b
711	}
712	
713	func deepEqualAny(a, b any) bool {
714		ab, _ := json.Marshal(a)
715		bb, _ := json.Marshal(b)
716		return string(ab) == string(bb)
717	}
718	
719	func itoa(n int) string {
720		if n == 0 {
721			return "0"
722		}
723		var buf [20]byte
724		i := len(buf)
725		for n > 0 {
726			i--
727			buf[i] = byte('0' + n%10)
728			n /= 10
729		}
730		return string(buf[i:])
731	}
732

